import{_ as a,o as d,c as e,a2 as r}from"./chunks/framework.CqpfiAoK.js";const s=JSON.parse('{"title":"প্রত্নতত্ত্ব চুক্তি মূল নীতি","description":"","frontmatter":{},"headers":[],"relativePath":"bn/84-考古协议总纲.md","filePath":"bn/84-考古协议总纲.md","lastUpdated":null}'),o={name:"bn/84-考古协议总纲.md"};function h(l,t,i,n,u,_){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="প্রত্নতত্ত্ব-চুক্তি-মূল-নীতি" tabindex="-1">প্রত্নতত্ত্ব চুক্তি মূল নীতি <a class="header-anchor" href="#প্রত্নতত্ত্ব-চুক্তি-মূল-নীতি" aria-label="Permalink to &quot;প্রত্নতত্ত্ব চুক্তি মূল নীতি&quot;">​</a></h1><table tabindex="0"><thead><tr><th>আইটেম</th><th>বিষয়বস্তু</th></tr></thead><tbody><tr><td>নথি নম্বর</td><td>84</td></tr><tr><td>মডিউল</td><td>আন্তঃ-তল মিথস্ক্রিয়া ও সময় নিয়ম</td></tr><tr><td>মূল কীওয়ার্ড</td><td>প্রত্নতত্ত্ব চুক্তি, প্রতিলিপি দর্পণ, বিচ্ছিন্ন স্থান, শুধুমাত্র জ্ঞান ফেরত, কম দূষণ</td></tr></tbody></table><h2 id="_1-প্রত্নতত্ত্ব-চুক্তির-অবস্থান-ও-লক্ষ্য" tabindex="-1">1. প্রত্নতত্ত্ব চুক্তির অবস্থান ও লক্ষ্য <a class="header-anchor" href="#_1-প্রত্নতত্ত্ব-চুক্তির-অবস্থান-ও-লক্ষ্য" aria-label="Permalink to &quot;1. প্রত্নতত্ত্ব চুক্তির অবস্থান ও লক্ষ্য&quot;">​</a></h2><p>আন্তঃ-তল প্রত্নতত্ত্ব ও সময় প্রত্যাবর্তন প্রত্নতত্ত্ব হলো অ্যাঙ্কর সিম্বায়োসিস সভ্যতার ঐতিহাসিক জ্ঞান অর্জন, মহাবিশ্বের বিবর্তন বোঝার গুরুত্বপূর্ণ উপায়। তবে, প্রত্নতত্ত্ব আচরণ নিজেই উচ্চ ঝুঁকিপূর্ণ — সরাসরি লক্ষ্য তল বা লক্ষ্য সময়কালে প্রবেশ করে প্রত্নতত্ত্ব খনন করা, লক্ষ্য বস্তুর উপর ভৌত ধ্বংস, আইন ব্যাঘাত ও সাংস্কৃতিক দূষণ সৃষ্টি করতে পারে। প্রত্নতত্ত্ব আচরণ নিয়ন্ত্রণ করতে, প্রত্নতত্ত্বের ঝুঁকি কমাতে, হেংইয়ান-ঝৌ একীভূত &quot;প্রত্নতত্ত্ব চুক্তি মূল নীতি&quot; প্রণয়ন করেছে, যা সব আন্তঃ-তল ও সময় প্রত্যাবর্তন প্রত্নতত্ত্ব কার্যকলাপের মূল অপারেশন নিয়ম হিসেবে কাজ করে।</p><p>প্রত্নতত্ত্ব চুক্তির মূল লক্ষ্য &quot;তিনটি সর্বোচ্চ সীমা&quot; হিসেবে সারাংশ করা যায়: সর্বোচ্চ সীমায় সম্পূর্ণ ঐতিহাসিক জ্ঞান অর্জন, সর্বোচ্চ সীমায় লক্ষ্য বস্তুর উপর হস্তক্ষেপ ও ধ্বংস কমানো, সর্বোচ্চ সীমায় প্রত্নতত্ত্ব কর্মীদের নিরাপত্তা নিশ্চিত করা। এই তিনটি লক্ষ্যের মধ্যে অভ্যন্তরীণ টান রয়েছে — জ্ঞান অর্জনের সম্পূর্ণতা প্রায়শই আরও গভীর যোগাযোগের দাবি করে, আর কম হস্তক্ষেপের নীতি আবার যোগাযোগের গভীরতা সীমাবদ্ধ করে। প্রত্নতত্ত্ব চুক্তির সমস্ত প্রণালী নকশা, এই তিনটির মধ্যে সর্বোত্তম ভারসাম্যের সন্ধান করার জন্যই।</p><p>প্রত্নতত্ত্ব চুক্তি নিম্নলিখিত পরিস্থিতিতে প্রযোজ্য: অজানা তলের সভ্যতার ধ্বংসস্তূপে প্রত্নতত্ত্ব তদন্ত, সময় প্রত্যাবর্তনের মাধ্যমে বিলুপ্ত সভ্যতার ঐতিহাসিক পুনরুদ্ধার, নিজের তলের প্রাচীন ধ্বংসস্তূপে আইন স্তরের গভীর প্রত্নতত্ত্ব, এবং আইন ভাঙা তলের প্রাচীন অবশিষ্টাংশে উদ্ধারমূলক খনন।</p><h2 id="_2-প্রত্নতত্ত্ব-পরিকল্পনার-তিনটি-উপাদান" tabindex="-1">2. প্রত্নতত্ত্ব পরিকল্পনার তিনটি উপাদান <a class="header-anchor" href="#_2-প্রত্নতত্ত্ব-পরিকল্পনার-তিনটি-উপাদান" aria-label="Permalink to &quot;2. প্রত্নতত্ত্ব পরিকল্পনার তিনটি উপাদান&quot;">​</a></h2><p>হেংইয়ান-ঝৌর মানক প্রত্নতত্ত্ব পরিকল্পনা তিনটি মূল উপাদান দ্বারা গঠিত, যাকে &quot;প্রত্নতত্ত্ব তিন উপাদান&quot; বলা হয়:</p><h3 id="_2-1-প্রতিলিপি-দর্পণ" tabindex="-1">2.1 প্রতিলিপি দর্পণ <a class="header-anchor" href="#_2-1-প্রতিলিপি-দর্পণ" aria-label="Permalink to &quot;2.1 প্রতিলিপি দর্পণ&quot;">​</a></h3><p>প্রতিলিপি দর্পণ হলো স্থান আইন নিয়মের উপর ভিত্তি করে তৈরি একটি উচ্চ-নির্ভুল প্রতিলিপি ডিভাইস, যা মূল বস্তুর সংস্পর্শে না এসেই লক্ষ্য অঞ্চলের পদার্থ, শক্তি ও তথ্য কাঠামোর 1:1 সম্পূর্ণ প্রতিলিপি তৈরি করতে সক্ষম। প্রতিলিপি দর্পণের কাজের নীতি হলো স্থান আইনের মাধ্যমে লক্ষ্য অঞ্চলের সমস্ত কণার অবস্থা ও শক্তি ক্ষেত্রের বিতরণ স্ক্যান করা, তারপর বিচ্ছিন্ন স্থানে একটি সম্পূর্ণ অভিন্ন প্রতিলিপি পুনর্নির্মাণ করা। প্রতিলিপি প্রক্রিয়া মূল বস্তুর কোনো অবস্থা পরিবর্তন করে না, তাই প্রত্নতত্ত্ব স্থানে কোনো ভৌত হস্তক্ষেপ সৃষ্টি করে না।</p><p>প্রতিলিপি দর্পণের প্রতিলিপির নির্ভুলতা উপ-পরমাণু স্তরে পৌঁছেছে, যা লক্ষ্য অঞ্চলের পদার্থ কাঠামো, শক্তির অবশিষ্টাংশ, চেতনার ছাপ এমনকি কার্য-কারণ শৃঙ্খলার টুকরো সম্পূর্ণরূপে ফিরিয়ে দিতে সক্ষম। প্রতিলিপির পরিসর প্রত্নতত্ত্বের চাহিদা অনুযায়ী সামঞ্জস্য করা যায়, সর্বনিম্ন প্রতিলিপি একক হলো একক প্রত্নবস্তু, সর্বোচ্চ সম্পূর্ণ ধ্বংসস্তূপ গোষ্ঠীকে কভার করতে পারে। প্রতিলিপির সময় প্রতিলিপির পরিসরের আকারের উপর নির্ভর করে, একক প্রত্নবস্তুর প্রতিলিপি সাধারণত কয়েক মিনিটে সম্পন্ন হয়, বড় ধ্বংসস্তূপ গোষ্ঠীর প্রতিলিপিতে কয়েক দিন লাগতে পারে।</p><h3 id="_2-2-বিচ্ছিন্ন-স্থান" tabindex="-1">2.2 বিচ্ছিন্ন স্থান <a class="header-anchor" href="#_2-2-বিচ্ছিন্ন-স্থান" aria-label="Permalink to &quot;2.2 বিচ্ছিন্ন স্থান&quot;">​</a></h3><p>বিচ্ছিন্ন স্থান হলো স্থান আইন নিয়ন্ত্রণ প্রযুক্তির মাধ্যমে নির্মিত স্বাধীন আইন অঞ্চল, যা প্রতিলিপি দর্পণ দ্বারা উত্পন্ন প্রত্নতত্ত্ব প্রতিলিপি বহন করার জন্য এবং প্রত্নতত্ত্ব কর্মীদের কর্মস্থল হিসেবে ব্যবহৃত হয়। বিচ্ছিন্ন স্থান ও লক্ষ্য তল বা লক্ষ্য সময়কালের মধ্যে সম্পূর্ণ আইন প্রাচীর দ্বারা পৃথক করা হয়, যা নিশ্চিত করে যে প্রত্নতত্ত্ব অপারেশন মূল লক্ষ্যের উপর কোনো বিপরীত প্রভাব ফেলবে না।</p><p>বিচ্ছিন্ন স্থানের অভ্যন্তরে আইন প্যারামিটার প্রত্নতত্ত্বের চাহিদা অনুযায়ী কাস্টমাইজ করা যায়, যার মধ্যে অন্তর্ভুক্ত: প্রত্নবস্তুর প্রতিলিপির স্থিতিশীলতা নিশ্চিত করতে লক্ষ্য তলের পরিবেশ প্যারামিটার অনুকরণ করা, প্রত্নতত্ত্ব গবেষণায় সহায়তা করার জন্য বিশেষ বিশ্লেষণ আইন ক্ষেত্র সেট করা, এবং প্রত্নতত্ত্ব কর্মীদের শক্তি ও চেতনা বাইরে যাওয়া প্রতিরোধ করার জন্য কঠোর দূষণ প্রতিরোধ ক্ষেত্র স্থাপন করা। বিচ্ছিন্ন স্থানের আকার চাহিদা অনুযায়ী প্রসারিত করা যায়, সর্বোচ্চ সম্পূর্ণ শহর-স্তরের ধ্বংসস্তূপ প্রতিলিপি ধারণ করতে পারে।</p><h3 id="_2-3-শুধুমাত্র-জ্ঞান-ফেরত" tabindex="-1">2.3 শুধুমাত্র জ্ঞান ফেরত <a class="header-anchor" href="#_2-3-শুধুমাত্র-জ্ঞান-ফেরত" aria-label="Permalink to &quot;2.3 শুধুমাত্র জ্ঞান ফেরত&quot;">​</a></h3><p>&quot;শুধুমাত্র জ্ঞান ফেরত&quot; হলো প্রত্নতত্ত্ব চুক্তির মূল নীতিগুলির মধ্যে একটি, যার অর্থ হলো প্রত্নতত্ত্ব প্রক্রিয়াতে লক্ষ্য বস্তু থেকে যা পাওয়া যায় তা শুধুমাত্র বিমূর্ত জ্ঞান ও তথ্য হতে পারে, কোনো পদার্থ, শক্তি বা জীবিত বস্তু ফেরত দেওয়া যাবে না। প্রত্নতত্ত্ব কর্মীরা বিচ্ছিন্ন স্থানে প্রতিলিপি গবেষণা করার পর, শুধুমাত্র গবেষণার সিদ্ধান্ত, ডেটা রেকর্ড ও বিশ্লেষণ রিপোর্টকে বিশুদ্ধ তথ্যের আকারে নিজের তলে ফিরিয়ে আনতে পারে, প্রতিলিপি নিজেই এবং প্রতিলিপি থেকে নেওয়া কোনো পদার্থের নমুনা অবশ্যই বিচ্ছিন্ন স্থানের মধ্যে ধ্বংস করতে হবে।</p><p>এই নীতির মূল উদ্দেশ্য হলো আন্তঃ-তল দূষণ ও টাইমলাইন ব্যাঘাত প্রতিরোধ করা। এমনকি প্রতিলিপি থেকে নেওয়া এককোণি ধুলোও লক্ষ্য তলের আইন তথ্য বহন করতে পারে, একবার নিজের তলের আইন নেটওয়ার্কে প্রবেশ করলে, অপ্রত্যাশিত পারস্পরিক বিক্রিয়া সৃষ্টি করতে পারে। অতএব, &quot;শুধুমাত্র জ্ঞান ফেরত&quot; একটি আলোচনাযোগ্য অপারেশন পরামর্শ নয়, বরং আইনি বাধ্যতামূলক শক্তি সম্পন্ন কঠোর নীতি।</p><h2 id="_3-প্রত্নতত্ত্ব-অপারেশনের-মানক-প্রক্রিয়া" tabindex="-1">3. প্রত্নতত্ত্ব অপারেশনের মানক প্রক্রিয়া <a class="header-anchor" href="#_3-প্রত্নতত্ত্ব-অপারেশনের-মানক-প্রক্রিয়া" aria-label="Permalink to &quot;3. প্রত্নতত্ত্ব অপারেশনের মানক প্রক্রিয়া&quot;">​</a></h2><p>একটি সম্পূর্ণ আন্তঃ-তল বা সময় প্রত্যাবর্তন প্রত্নতত্ত্ব অপারেশন নিম্নলিখিত মানক প্রক্রিয়া অনুসরণ করে:</p><table tabindex="0"><thead><tr><th>পর্যায়</th><th>অপারেশন বিষয়বস্তু</th><th>দায়ী পক্ষ</th><th>সময়ের রেফারেন্স</th></tr></thead><tbody><tr><td>প্রথম পর্যায়: প্রকল্প অনুমোদন</td><td>প্রত্নতত্ত্ব আবেদন জমা দেওয়া, প্রত্নতত্ত্বের লক্ষ্য, পরিসর ও পরিকল্পনা স্পষ্ট করা, A স্তরের অতিক্রম অনুমতি বা প্রত্যাবর্তন অনুমতি পাওয়া</td><td>প্রত্নতত্ত্ব টিম→তল ব্যবস্থাপনা ব্যুরো/সময় আইন কমিটি</td><td>7-30 দিন</td></tr><tr><td>দ্বিতীয় পর্যায়: আগে পর্যবেক্ষণ</td><td>&quot;আগে পর্যবেক্ষণ তারপর সীমিত হস্তক্ষেপ&quot; নীতি অনুসারে, লক্ষ্য অঞ্চলে 72 ঘন্টার বেশি বিশুদ্ধ পর্যবেক্ষণ করা</td><td>প্রত্নতত্ত্ব টিম</td><td>72 ঘন্টার বেশি</td></tr><tr><td>তৃতীয় পর্যায়: প্রতিলিপি দর্পণ স্থাপন</td><td>লক্ষ্য অঞ্চলের কাছে নিরাপদ অবস্থানে প্রতিলিপি দর্পণ স্থাপন করা, প্রতিলিপির পরিসর ও নির্ভুলতা প্যারামিটার সেট করা</td><td>প্রযুক্তি গ্রুপ</td><td>কয়েক ঘন্টা থেকে কয়েক দিন</td></tr><tr><td>চতুর্থ পর্যায়: প্রতিলিপি তৈরি</td><td>প্রতিলিপি দর্পণ চালু করা, লক্ষ্য অঞ্চলকে সম্পূর্ণরূপে পূর্বনির্মিত বিচ্ছিন্ন স্থানে প্রতিলিপি করা</td><td>প্রযুক্তি গ্রুপ</td><td>কয়েক মিনিট থেকে কয়েক দিন</td></tr><tr><td>পঞ্চম পর্যায়: বিচ্ছিন্ন স্থানে প্রত্নতত্ত্ব</td><td>প্রত্নতত্ত্ব কর্মীরা বিচ্ছিন্ন স্থানে প্রবেশ করে, প্রতিলিপির পদ্ধতিগত খনন, বিশ্লেষণ ও গবেষণা করা</td><td>প্রত্নতত্ত্ব টিম</td><td>কয়েক দিন থেকে কয়েক বছর</td></tr><tr><td>ষষ্ঠ পর্যায়: জ্ঞান সংগ্রহ</td><td>প্রত্নতত্ত্বের ফলাফল সংগ্রহ করা, গবেষণা রিপোর্ট ও জ্ঞান ডেটাবেস তৈরি করা, নিশ্চিত করা যে সব ফলাফল বিশুদ্ধ তথ্যের আকারে আছে</td><td>প্রত্নতত্ত্ব টিম</td><td>কয়েক দিন থেকে কয়েক মাস</td></tr><tr><td>সপ্তম পর্যায়: প্রত্যাহার ও ধ্বংস</td><td>প্রত্নতত্ত্ব কর্মীরা বিচ্ছিন্ন স্থান থেকে প্রত্যাহার করে, সমস্ত প্রতিলিপি পদার্থ ও শক্তির অবশিষ্টাংশ ধ্বংস করে, বিচ্ছিন্ন স্থান বন্ধ করে</td><td>প্রযুক্তি গ্রুপ+তত্ত্বাবধান গ্রুপ</td><td>কয়েক ঘন্টা</td></tr><tr><td>অষ্টম পর্যায়: পরবর্তী অডিট</td><td>সম্পূর্ণ প্রত্নতত্ত্ব রিপোর্ট জমা দেওয়া, সময় আইন অডিট কমিটি বা তল ব্যবস্থাপনা ব্যুরোর পরবর্তী অডিট গ্রহণ করা</td><td>অডিট কমিটি</td><td>30 দিনের মধ্যে</td></tr></tbody></table><h2 id="_4-প্রত্নতত্ত্ব-কর্মীদের-যোগ্যতা-ও-নৈতিক-প্রয়োজনীয়তা" tabindex="-1">4. প্রত্নতত্ত্ব কর্মীদের যোগ্যতা ও নৈতিক প্রয়োজনীয়তা <a class="header-anchor" href="#_4-প্রত্নতত্ত্ব-কর্মীদের-যোগ্যতা-ও-নৈতিক-প্রয়োজনীয়তা" aria-label="Permalink to &quot;4. প্রত্নতত্ত্ব কর্মীদের যোগ্যতা ও নৈতিক প্রয়োজনীয়তা&quot;">​</a></h2><p>আন্তঃ-তল ও সময় প্রত্যাবর্তন প্রত্নতত্ত্বে নিয়োজিত ব্যক্তিদের অবশ্যই নিম্নলিখিত যোগ্যতা থাকতে হবে: স্থান আইন নিয়ন্ত্রণ ব্যবস্থার তৃতীয় স্তর বা তার বেশি সাধনা, প্রত্নতত্ত্ব নৈতিক কমিটির যোগ্যতা সার্টিফিকেশন পাশ, 100 ঘন্টার বেশি সিমুলেশন প্রত্নতত্ত্ব প্রশিক্ষণ সম্পন্ন, এবং সিম্বায়োসিস আইন লঙ্ঘনের কোনো রেকর্ড নেই।</p><p>প্রত্নতত্ত্ব কর্মীদের অবশ্যই নিম্নলিখিত নৈতিক প্রয়োজনীয়তা মানতে হবে: লক্ষ্য সভ্যতার সংস্কৃতি ও বিশ্বাসকে সম্মান করা, গবেষণায় সাংস্কৃতিক বৈষম্য বা মূল্য বিচার করা নিষিদ্ধ; প্রত্নতত্ত্ব স্থানের অখণ্ডতা রক্ষা করা, প্রত্নবস্তু অর্জনের জন্য ধ্বংসস্তূপের কাঠামো ধ্বংস করা নিষিদ্ধ; প্রত্নতত্ত্বের আবিষ্কার সত্যিকারেরভাবে রেকর্ড ও রিপোর্ট করা, প্রত্নতত্ত্ব ডেটা বিকৃত বা গোপন করা নিষিদ্ধ; এবং &quot;শুধুমাত্র জ্ঞান ফেরত&quot; নীতি মানা, বিচ্ছিন্ন স্থান থেকে বেরিয়ে আসার সময় নিজের ইচ্ছায় কোনো পদার্থের নমুনা বহন করা নিষিদ্ধ।</p><h2 id="উপসংহার" tabindex="-1">উপসংহার <a class="header-anchor" href="#উপসংহার" aria-label="Permalink to &quot;উপসংহার&quot;">​</a></h2><p>প্রত্নতত্ত্ব চুক্তি মূল নীতি হলো হেংইয়ান-ঝৌর জ্ঞান অনুসন্ধান ও সভ্যতা সুরক্ষার মধ্যে প্রতিষ্ঠিত প্রণালী সেতু। এটি প্রতিলিপি দর্পণ, বিচ্ছিন্ন স্থান ও শুধুমাত্র জ্ঞান ফেরত তিন উপাদানকে প্রযুক্তিগত সহায়তা হিসেবে, মানক প্রক্রিয়াকে অপারেশন কাঠামো হিসেবে, কর্মীদের যোগ্যতা ও নৈতিক প্রয়োজনীয়তাকে মানবিক নিশ্চয়তা হিসেবে নিয়ে, &quot;কম দূষণ, উচ্চ দক্ষতা, ট্রেসযোগ্য&quot; এর একটি প্রত্নতত্ত্ব প্যারাডাইম গঠন করেছে। এই প্যারাডাইম নিশ্চিত করে যে হেংইয়ান-ঝৌ ঐতিহাসিক সত্যের সন্ধান করার সাথে সাথে, সবসময় অন্য সভ্যতা ও যুগের প্রতি সর্বোচ্চ শ্রদ্ধা বজায় রাখে।</p><h2 id="সম্পর্কিত-নথি" tabindex="-1">সম্পর্কিত নথি <a class="header-anchor" href="#সম্পর্কিত-নথি" aria-label="Permalink to &quot;সম্পর্কিত নথি&quot;">​</a></h2><ul><li>85-প্রতিলিপি দর্পণ অন্যতল প্রত্নতত্ত্ব পরিকল্পনা</li><li>86-বিচ্ছিন্ন স্থান কম দূষণ প্রক্রিয়া</li><li>87-শুধুমাত্র জ্ঞান ফেরত নীতি</li></ul>',27)])])}const q=a(o,[["render",h]]);export{s as __pageData,q as default};
